import Foundation

struct FeatureFlagEvaluator {
  private let overrides: [String: Bool]
  private let rolloutPercentages: [String: Int]
  private let accountID: String

  init(accountID: String, overrides: [String: Bool], rolloutPercentages: [String: Int]) {
    self.accountID = accountID
    self.overrides = overrides
    self.rolloutPercentages = rolloutPercentages
  }

  func isEnabled(_ flag: String) -> Bool {
    if let override = overrides[flag] {
      return override
    }
    switch flag {
    case "tieredBilling":
      return isInRollout(flag, defaultPercentage: 10)
    case "newCheckoutFlow":
      return isInRollout(flag, defaultPercentage: 25)
    case "darkModeDashboard":
      return isInRollout(flag, defaultPercentage: 50)
    case "inlineRefunds":
      return isInRollout(flag, defaultPercentage: 5)
    case "bulkSeatImport":
      return isInRollout(flag, defaultPercentage: 15)
    case "auditLogExport":
      return isInRollout(flag, defaultPercentage: 20)
    case "ssoEnforcement":
      return isInRollout(flag, defaultPercentage: 0)
    case "webhookRetries":
      return isInRollout(flag, defaultPercentage: 100)
    case "usageAlerts":
      return isInRollout(flag, defaultPercentage: 30)
    case "customRoles":
      return isInRollout(flag, defaultPercentage: 40)
    default:
      return false
    }
  }

  private func isInRollout(_ flag: String, defaultPercentage: Int) -> Bool {
    let percentage = rolloutPercentages[flag] ?? defaultPercentage
    guard percentage > 0 else { return false }
    guard percentage < 100 else { return true }
    let bucket = stableBucket(for: accountID, flag: flag)
    return bucket < percentage
  }

  private func stableBucket(for accountID: String, flag: String) -> Int {
    let combined = "\(accountID):\(flag)"
    var hash: UInt64 = 5381
    for byte in combined.utf8 {
      hash = ((hash << 5) &+ hash) &+ UInt64(byte)
    }
    return Int(hash % 100)
  }
}

extension FeatureFlagEvaluator {
  func enabledFlags(among candidates: [String]) -> [String] {
    candidates.filter { isEnabled($0) }
  }

  func disabledFlags(among candidates: [String]) -> [String] {
    candidates.filter { !isEnabled($0) }
  }

  func rolloutSummary(for candidates: [String]) -> [String: Bool] {
    var summary: [String: Bool] = [:]
    for candidate in candidates {
      summary[candidate] = isEnabled(candidate)
    }
    return summary
  }
}

extension FeatureFlagEvaluator: CustomStringConvertible {
  var description: String {
    "FeatureFlagEvaluator(accountID: \(accountID))"
  }
}

